/* ===== admin views ===== */
const MLAB=(n)=>{const o=[];for(let i=n-1;i>=0;i--){const d=addM(new Date(TODAY.getFullYear(),TODAY.getMonth(),1),-i);o.push(mon(d.getMonth()))}return o};
const feeByMonth=()=>MLAB(12).map((l,i)=>{const d=addM(new Date(TODAY.getFullYear(),TODAY.getMonth(),1),i-11);return DB.payments.filter(p=>p.kind==='fee'&&p.status==='paid'&&p.paidOn&&monthKey(p.paidOn)===monthKey(d)).reduce((a,p)=>a+p.amount,0)});
const signedPct=()=>pct(DB.contracts.filter(c=>c.signedL&&c.signedT).length,DB.contracts.length||1)+'%';
const renewPct=()=>pct(DB.contracts.filter(c=>c.renewal&&c.renewal.state==='accepted').length,DB.contracts.filter(c=>c.renewal).length||1)+'%';
const collPct=()=>pct(DB.payments.filter(p=>p.kind==='rent'&&p.status==='paid').reduce((a,p)=>a+p.amount,0),DB.payments.filter(p=>p.kind==='rent'&&p.status!=='upcoming').reduce((a,p)=>a+p.amount,0)||1)+'%';
const feeRevenue=()=>DB.payments.filter(p=>p.kind==='fee'&&p.status==='paid').reduce((a,p)=>a+p.amount,0);
const rentCollected=()=>DB.payments.filter(p=>p.kind==='rent'&&p.status==='paid').reduce((a,p)=>a+p.amount,0);
const methBars=()=>{const m={};DB.payments.filter(p=>p.status==='paid').forEach(p=>{m[p.method||'—']=(m[p.method||'—']||0)+1});const tot=Object.values(m).reduce((a,b)=>a+b,0)||1;return hbars(Object.keys(m).map(k=>({l:T(...(METH[k]||[k,k])),v:m[k],t:pct(m[k],tot)+'%'})),'var(--teal)')};
const roleChip=u=>u.role==='admin'?chip(rawL(DB.roles.find(r=>r.id===u.sub)||DB.roles[0]),'gold nd'):chip(T(ROLES[u.role].ar,ROLES[u.role].en),u.role==='landlord'?'brand nd':'teal nd');
const USTAT=s=>chip({active:T('نشط','Active'),pending:T('بانتظار التوثيق','Pending'),suspended:T('موقوف','Suspended')}[s]||s,{active:'ok',pending:'warn',suspended:'bad'}[s]);

function ovAdmin(){
  const q={ver:DB.verif.length,rev:DB.contracts.filter(c=>c.status==='under_review').length,tk:DB.tickets.filter(t=>t.st==='open').length,dis:DB.contracts.filter(c=>c.status==='disputed').length};
  const st={};DB.contracts.forEach(c=>{const s=cst(c);st[s]=(st[s]||0)+1});
  const gov={};DB.props.forEach(p=>{const g=AREAS[p.area].gov;gov[g]=(gov[g]||0)+1});const gv=Object.keys(GOV).map(k=>({l:GOV[k],v:DB.units.filter(u=>propOf(u.prop)&&AREAS[propOf(u.prop).area]&&AREAS[propOf(u.prop).area].gov===k).length}));
  const act=DB.contracts.filter(c=>cst(c)==='active').length;
  const feeMonth=DB.payments.filter(p=>p.kind==='fee'&&p.status==='paid'&&p.paidOn&&monthKey(p.paidOn)===monthKey(TODAY)).reduce((a,p)=>a+p.amount,0);
  const mContracts=MLAB(12).map((l,i)=>{const d=addM(new Date(TODAY.getFullYear(),TODAY.getMonth(),1),i-11);return DB.contracts.filter(c=>monthKey(c.created)===monthKey(d)).length});
  return pageHead(T(`مرحباً، ${dispName().split(' ')[0]}`,`Welcome, ${dispName().split(' ')[0]}`),T('مؤشرات المنصة وقوائم العمل اليوم','Platform indicators and today’s work queues'),btn(T('تقرير اليوم','Daily report'),'nav',{v:'reports'},'','chart'))+
  `<div class="kpis">${kpi(T('عقود فعّالة','Active leases'),fmt(act),T(`من ${DB.contracts.length} عقداً`,`of ${DB.contracts.length} contracts`),'file')}${kpi(T('مستخدمون مسجّلون','Registered users'),fmt(DB.users.length),T(`${DB.users.filter(u=>u.verified).length} موثّق`,`${DB.users.filter(u=>u.verified).length} verified`),'users')}${kpi(T('عقارات مسجّلة','Registered properties'),fmt(DB.props.length),T(`${DB.units.length} وحدة`,`${DB.units.length} units`),'building')}${kpi(T('إيراد الرسوم هذا الشهر','Fee revenue this month'),`${fmt(feeMonth)}<small>${cur()}</small>`,T('الرسوم المحصّلة فعلياً','Fees actually collected'),'coins')}</div>
  <div class="g2"><div class="card"><div class="ch"><h3>${T('العقود المنشأة شهرياً','Contracts created per month')}</h3></div><div class="cb">${lineChart(MLAB(12),[mContracts],['var(--brand)'],{label:T('عقود','Contracts')})}</div></div>
  <div class="card"><div class="ch"><h3>${T('قوائم العمل','Work queues')}</h3></div>${[[T('طلبات توثيق','Verification requests'),q.ver,'verification','shield','brand',''],[T('عقود قيد المراجعة','Contracts under review'),q.rev,'contracts','file','gold','review'],[T('تذاكر مفتوحة','Open tickets'),q.tk,'tickets','msg','info',''],[T('عقود متنازع عليها','Disputed contracts'),q.dis,'contracts','alert','bad','review']].map(x=>`<div class="li click" data-a="${x[2]==='contracts'?'goct':'nav'}" data-v="${x[2]}" data-f="${x[5]}"><span class="ii ${x[4]}">${ic(x[3],17)}</span><div class="tx b sm">${x[0]}</div><b class="num" style="font-size:20px">${x[1]}</b>${ic(S.lang==='ar'?'left':'right',16)}</div>`).join('')}</div></div>
  <div class="g2e"><div class="card"><div class="ch"><h3>${T('توزيع العقود حسب المحافظة','Leases by governorate')}</h3></div><div class="cb">${hbars(gv.map(g=>({l:L(g.l),v:g.v})),'var(--teal)')}</div></div>
  <div class="card"><div class="ch"><h3>${T('حالة الربط مع الجهات','Integration health')}</h3>${btn(T('إدارة','Manage'),'nav',{v:'integrations'},'sm ghost')}</div>${DB.integ.map(i=>`<div class="li" style="padding:10px 20px"><span class="ii ${i.st==='ok'?'ok':i.st==='warn'?'warn':''}">${ic('plug',16)}</span><div class="tx sm b">${L(i.name)}</div>${chip(i.st==='ok'?T('متصل','Online'):i.st==='warn'?T('بطيء','Degraded'):T('متوقف','Off'),i.st==='ok'?'ok':i.st==='warn'?'warn':'')}</div>`).join('')}</div></div>
  <div class="card" style="margin-top:20px"><div class="ch"><h3>${T('آخر العمليات','Recent activity')}</h3>${btn(T('سجل التدقيق','Audit log'),'nav',{v:'audit'},'sm ghost')}</div>${DB.audit.slice(0,4).map(a=>`<div class="li"><span class="av">${esc(initials(uname(a.u)))}</span><div class="tx"><div class="sm b">${T(a.ar,a.en)}</div><div class="xs mut3">${uname(a.u)} · ${esc(a.ent)}</div></div><span class="xs mut3">${rel(a.t)}</span></div>`).join('')}</div>`;
}
A.goct=d=>{S.f.contracts.st=d.f||'all';S.f.contracts.q='';go('contracts')};

/* users */
V.users=()=>{
  const F=S.f.users;const q=F.q.toLowerCase();const l=DB.users.filter(u=>(F.role==='all'||u.role===F.role)&&(F.st==='all'||u.status===F.st)&&(!q||(u.name.ar+u.name.en+u.email+u.cpr).toLowerCase().includes(q)));
  return pageHead(T('المستخدمون','Users'),T('إدارة الحسابات والتوثيق والصلاحيات','Manage accounts, verification and permissions'),btn(T('تصدير','Export'),'modal',{t:'export',kind:'users'},'','download')+btn(T('دعوة مستخدم','Invite user'),'modal',{t:'invite'},'pri','plus'))+
  `<div class="tb">${searchBox('usQ',F.q,T('ابحث بالاسم أو البريد أو الرقم الشخصي…','Search name, email or CPR…'),'us')}${seg([['all',T('الكل','All')],['landlord',T('مؤجرون','Landlords')],['tenant',T('مستأجرون','Tenants')],['admin',T('الإدارة','Staff')]],F.role,'seg','data-k="users.role"')}${seg([['all',T('كل الحالات','Any status')],['active',T('نشط','Active')],['pending',T('معلّق','Pending')],['suspended',T('موقوف','Suspended')]],F.st,'seg','data-k="users.st"')}</div>
  ${table([{h:T('المستخدم','User'),f:u=>`<div class="ent">${ava(rawL(u.name))}<div><b>${L(u.name)}</b><small dir="ltr" style="text-align:start">${esc(u.email)}</small></div></div>`},{h:T('الدور','Role'),f:roleChip},{h:T('الرقم الشخصي','CPR'),f:u=>`<span class="num" dir="ltr">•••••• ${esc(u.cpr.slice(-3))}</span>`},{h:T('انضم في','Joined'),f:u=>fd(u.joined)},{h:T('التوثيق','Verified'),f:u=>u.verified?`<span style="color:var(--ok)">${ic('check',18)}</span>`:`<span class="mut3">—</span>`},{h:T('الحالة','Status'),f:u=>USTAT(u.status)},{h:'',c:'ac',f:u=>ibtn('eye','openuser',{id:u.id},T('عرض','View'))}],l.map(u=>Object.assign({},u,{_a:'openuser'})))}
  <div class="xs mut3" style="margin-top:10px">${T(`عرض ${l.length} من ${DB.users.length} مستخدماً`,`Showing ${l.length} of ${DB.users.length} users`)}</div>`;
};
IN.us=v=>{S.f.users.q=v;renderView()};
A.openuser=d=>openModal('user',{id:d.id});
MOD.user=d=>{const u=userOf(d.id);const cs=DB.contracts.filter(c=>c.landlord===u.id||c.tenant===u.id);const ps=DB.props.filter(p=>p.owner===u.id);
  return {sheet:1,title:L(u.name),body:`<div class="row wrapf" style="gap:14px;margin-bottom:16px">${ava(rawL(u.name),'lg')}<div style="flex:1"><div class="row wrapf">${roleChip(u)}${USTAT(u.status)}${u.verified?chip(T('هوية موثّقة','ID verified'),'ok'):chip(T('غير موثّق','Unverified'),'warn')}</div><div class="sm mut" style="margin-top:6px">${T('انضم','Joined')} ${fd(u.joined)}</div></div></div>
  <dl class="kv"><dt>${T('الرقم الشخصي','CPR')}</dt><dd class="num" dir="ltr">${esc(u.cpr)}</dd><dt>${T('الهاتف','Phone')}</dt><dd dir="ltr">${esc(u.phone)}</dd><dt>${T('البريد','Email')}</dt><dd dir="ltr">${esc(u.email)}</dd><dt>${T('عدد العقود','Contracts')}</dt><dd>${cs.length}</dd>${ps.length?`<dt>${T('العقارات','Properties')}</dt><dd>${ps.length}</dd>`:''}</dl>
  ${cs.length?`<hr class="hr"><h4 style="margin-bottom:8px">${T('العقود','Contracts')}</h4>${cs.map(c=>`<div class="li click" style="padding:10px 0" data-a="cmdgo" data-k="contract" data-id="${c.id}"><span class="ii teal">${ic('file',16)}</span><div class="tx sm"><b dir="ltr">${esc(c.no)}</b></div>${CSTATUS(cst(c))}</div>`).join('')}`:''}`,
      foot:`${!u.verified?`<button class="btn" data-a="uverify" data-id="${u.id}">${ic('check',16)}${T('اعتماد التوثيق','Verify')}</button>`:''}<button class="btn" data-a="modal" data-t="useredit" data-id="${u.id}">${ic('edit',16)}${T('تعديل','Edit')}</button><button class="btn" data-a="modal" data-t="userrole" data-id="${u.id}">${ic('users',16)}${T('الدور','Role')}</button><button class="btn" data-a="userreset" data-id="${u.id}">${ic('key',16)}${T('إعادة كلمة المرور','Reset password')}</button><button class="btn" data-a="uexport" data-id="${u.id}">${ic('download',16)}${T('تصدير البيانات','Export data')}</button><button class="btn ${u.status==='suspended'?'pri':'danger'}" data-a="ustatus" data-id="${u.id}">${u.status==='suspended'?T('إعادة التفعيل','Reactivate'):T('إيقاف الحساب','Suspend account')}</button>`}};
MOD.useredit=d=>{const u=userOf(d.id);return {title:T('تعديل مستخدم','Edit user'),cls:'narrow',body:`<div class="fg">${field(T('الاسم (عربي)','Name (Arabic)'),inp('ueAr',u.name.ar,'text','data-focus'),'full')}${field(T('الاسم (English)','Name (English)'),inp('ueEn',u.name.en,'text','dir="ltr"'),'full')}${field(T('البريد الإلكتروني','Email'),inp('ueMail',u.email,'email','dir="ltr" style="text-align:start"'),'full')}${field(T('رقم الهاتف','Phone'),inp('uePhone',u.phone||'','tel','dir="ltr" style="text-align:start"'))}${field(T('الرقم الشخصي (CPR)','CPR number'),inp('ueCpr',u.cpr||'','text','inputmode="numeric" dir="ltr" style="text-align:start"'))}</div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="usersave" data-id="${u.id}">${T('حفظ','Save')}</button>`}};
A.usersave=async d=>{const ar=val('ueAr').trim();if(!ar){toast(T('أدخل الاسم','Enter the name'),true);return}
  try{await API.post('/api/users/'+d.id,{nameAr:ar,nameEn:val('ueEn').trim()||ar,email:val('ueMail').trim(),phone:val('uePhone').trim(),cpr:val('ueCpr').trim()});await refresh();openModal('user',{id:d.id});toast(T('تم حفظ البيانات','Details saved'))}
  catch(e){const m={email_taken:T('البريد مستخدم بالفعل','Email already in use'),invalid_email:T('بريد غير صحيح','Invalid email')};apiError(e,m[e.error]||'تعذّر الحفظ',m[e.error]||'Could not save')}};
MOD.userrole=d=>{const u=userOf(d.id);const cur=u.role==='admin'?'admin:'+(u.sub||'super'):u.role;return {title:T('تغيير الدور','Change role'),cls:'narrow',body:`<div class="col">${field(T('الدور','Role'),sel('urRole',[['landlord',T('مؤجر','Landlord')],['tenant',T('مستأجر','Tenant')],...DB.roles.map(r=>['admin:'+r.id,T('موظف: ','Staff: ')+L(r)])],cur))}<div class="hint">${T('تغيير الدور يغيّر الصلاحيات فوراً.','Changing the role changes permissions immediately.')}</div></div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="userrolesave" data-id="${u.id}">${T('حفظ','Save')}</button>`}};
A.userrolesave=async d=>{try{await API.post('/api/users/'+d.id+'/role',{role:val('urRole')});await refresh();openModal('user',{id:d.id});toast(T('تم تغيير الدور','Role changed'))}catch(e){apiError(e,'تعذّر التغيير','Could not change the role')}};
A.userreset=async d=>{try{const r=await API.post('/api/users/'+d.id+'/reset-password');toast(T('كلمة مرور مؤقتة: ','Temporary password: ')+r.tempPassword,null,{a:'copytext',id:r.tempPassword,label:T('نسخ','Copy')})}catch(e){apiError(e,'تعذّر إعادة التعيين','Could not reset the password')}};
A.copytext=d=>{try{navigator.clipboard.writeText(d.id);toast(T('تم النسخ','Copied'))}catch(e){}};
A.uexport=d=>download('/api/users/'+d.id+'/export');
A.ustatus=async d=>{try{await afterMutation(API.post('/api/users/'+d.id+'/status'));closeModal();toast(T('تم تحديث حالة الحساب','Account status updated'))}catch(e){apiError(e,'تعذّر التحديث','Could not update')}};
A.uverify=async d=>{try{await afterMutation(API.post('/api/users/'+d.id+'/verify'));closeModal();toast(T('تم اعتماد التوثيق','Verification approved'))}catch(e){apiError(e,'تعذّر الاعتماد','Could not approve')}};
MOD.invite=()=>({title:T('دعوة مستخدم','Invite a user'),cls:'narrow',body:`<div class="fg">${field(T('الاسم الكامل','Full name'),inp('ivName','','text','data-focus'),'full')}${field(T('البريد الإلكتروني','Email'),inp('ivMail','','email','dir="ltr" style="text-align:start"'),'full')}${field(T('نوع الحساب','Account type'),sel('ivRole',[['landlord',T('مؤجر','Landlord')],['tenant',T('مستأجر','Tenant')],...DB.roles.map(r=>['admin:'+r.id,T('موظف: ','Staff: ')+L(r)])],'tenant'),'full')}</div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="invsave">${ic('send',16)}${T('إرسال الدعوة','Send invite')}</button>`});
A.invsave=async()=>{const n=val('ivName').trim(),m=val('ivMail').trim();if(!n||!/.+@.+\..+/.test(m)){toast(T('أدخل الاسم وبريداً صحيحاً','Enter a name and a valid email'),true);return}
  try{const r=await API.post('/api/users/invite',{name:n,email:m,role:val('ivRole')});await refresh();closeModal();renderView();toast(T('تم إرسال الدعوة — كلمة مرور مؤقتة: ','Invitation sent — temp password: ')+r.tempPassword)}catch(e){apiError(e,'تعذّر إرسال الدعوة','Could not send the invite')}};

/* verification */
V.verification=()=>pageHead(T('طلبات التوثيق','Verification requests'),T('راجع المستندات واعتمد الهويات وسندات الملكية','Review documents and approve identities and title deeds'))+
  (DB.verif.length?`<div class="g4" style="grid-template-columns:repeat(auto-fill,minmax(300px,1fr))">${DB.verif.map(v=>{const u=userOf(v.u);const p=v.prop?propOf(v.prop):null;return `<div class="card"><div class="cb col"><div class="row">${ava(rawL(u.name))}<div style="flex:1"><b>${L(u.name)}</b><div class="xs mut3">${T(ROLES[u.role].ar,ROLES[u.role].en)} · ${rel(v.t)}</div></div>${chip(rawL(VK[v.kind]),'gold nd')}</div>
   <div style="border:1.5px dashed var(--line);border-radius:10px;padding:18px;text-align:center;background:var(--sf2)" class="mut3">${ic(v.kind==='deed'?'file':v.kind==='phone'?'phone':'user',26)}<div class="xs" style="margin-top:4px">${p?L(p.name)+' · '+esc(p.deed):T('مستند مرفوع من المستخدم','Document uploaded by the user')}</div></div>
   <div class="row">${btn(T('اعتماد','Approve'),'vapprove',{id:v.id},'pri sm','check')}${btn(T('رفض','Reject'),'modal',{t:'reject',k:'verif',id:v.id},'danger sm')}${btn(T('المستخدم','Profile'),'openuser',{id:u.id},'ghost sm')}</div></div></div>`}).join('')}</div>`:`<div class="card">${empty(T('لا توجد طلبات','Queue is empty'),T('تمت مراجعة كل الطلبات. أحسنتم!','All requests have been reviewed.'),'check')}</div>`);
A.vapprove=async d=>{try{await afterMutation(API.post('/api/verification/'+d.id+'/approve'));toast(T('تم اعتماد الطلب','Request approved'))}catch(e){apiError(e,'تعذّر الاعتماد','Could not approve')}};
MOD.reject=d=>({title:T('سبب الرفض','Reason for rejection'),cls:'narrow',body:`<div class="col">${field(T('السبب','Reason'),sel('rjWhy',[['blur',T('المستند غير واضح','Document is unclear')],['mismatch',T('البيانات لا تتطابق','Details do not match')],['expired',T('المستند منتهي الصلاحية','Document has expired')],['other',T('سبب آخر','Other')]],'blur'))}${field(T('ملاحظة للمستخدم','Note to user'),`<textarea class="ta" id="rjNote" style="min-height:70px"></textarea>`)}</div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn danger" data-a="doreject" data-k="${d.k}" data-id="${d.id}">${T('تأكيد الرفض','Confirm rejection')}</button>`});
A.doreject=async d=>{try{
    if(d.k==='contract')await afterMutation(API.post('/api/contracts/'+d.id+'/reject'));
    else await afterMutation(API.post('/api/verification/'+d.id+'/reject'));
    closeModal();toast(T('تم الرفض وإشعار المستخدم','Rejected and user notified'))
  }catch(e){apiError(e,'تعذّر الرفض','Could not reject')}};

/* properties (admin) */
function propsAdmin(){
  const q=S.f.props.q.toLowerCase();const l=DB.props.filter(p=>!q||(p.name.ar+p.name.en+p.deed+L(AREAS[p.area])+uname(p.owner)).toLowerCase().includes(q));
  return pageHead(T('العقارات','Properties'),T('مراجعة العقارات المسجّلة وكشف التكرار','Review registered properties and detect duplicates'))+
  `<div class="tb">${searchBox('propQ',S.f.props.q,T('ابحث بالعقار أو المالك أو رقم السند…','Search property, owner or deed no…'),'props')}</div>`+
  table([{h:T('العقار','Property'),f:p=>`<b>${L(p.name)}</b><small class="xs mut3" style="display:block">${L(AREAS[p.area])} · ${L(PT[p.type])}</small>`},{h:T('المالك','Owner'),f:p=>uname(p.owner)},{h:T('سند الملكية','Deed'),f:p=>`<span class="num" dir="ltr">${esc(p.deed)}</span>`},{h:T('الوحدات','Units'),f:p=>DB.units.filter(u=>u.prop===p.id).length},{h:T('الحالة','Status'),f:p=>(p.verified?chip(T('موثّق','Verified'),'ok'):chip(T('قيد التوثيق','Pending'),'warn'))+(p.dup?' '+chip(T('اشتباه تكرار','Possible duplicate'),'bad'):'')},{h:'',c:'ac',f:p=>ibtn('eye','modal',{t:'prop',id:p.id},T('الوحدات','Units'))+(p.verified?'':btn(T('توثيق','Verify'),'pverify',{id:p.id},'sm'))+(p.dup?btn(T('حلّ التكرار','Clear flag'),'pdup',{id:p.id},'sm'):'')}],l);
}
A.pverify=async d=>{try{await afterMutation(API.post('/api/properties/'+d.id+'/verify'));toast(T('تم توثيق العقار','Property verified'))}catch(e){apiError(e,'تعذّر التوثيق','Could not verify')}};
A.pdup=async d=>{try{await afterMutation(API.post('/api/properties/'+d.id+'/clear-duplicate'));toast(T('تم إغلاق التنبيه','Flag cleared'))}catch(e){apiError(e,'تعذّر التنفيذ','Could not clear the flag')}};

/* payments & fees (admin) */
function payAdmin(){
  const q=S.f.ledger.q.toLowerCase();const l=DB.payments.filter(p=>p.status==='paid').sort((a,b)=>b.paidOn-a.paidOn||b.due-a.due).filter(p=>!q||(p.receipt+ctOf(p.c).no+uname(ctOf(p.c).tenant)).toLowerCase().includes(q)).slice(0,25);
  const pend=DB.refunds.filter(r=>r.st==='pending');
  return pageHead(T('المدفوعات والرسوم','Payments & fees'),T('سجل المعاملات وإعداد الرسوم والاسترجاع','Transaction ledger, fee setup and refunds'),btn(T('تصدير','Export'),'modal',{t:'export',kind:'payments'},'','download'))+
  `<div class="kpis">${kpi(T('معاملات هذا الشهر','Transactions this month'),fmt(DB.payments.filter(p=>p.status==='paid'&&p.paidOn&&monthKey(p.paidOn)===monthKey(TODAY)).length),'','receipt')}${kpi(T('إيراد الرسوم','Fee revenue'),`${fmt(DB.payments.filter(p=>p.kind==='fee'&&p.status==='paid').reduce((a,p)=>a+p.amount,0))}<small>${cur()}</small>`,T('إجمالي المحصّل','Total collected'),'coins')}${kpi(T('إيجار محصّل','Rent collected'),`${fmt(DB.payments.filter(p=>p.kind==='rent'&&p.status==='paid').reduce((a,p)=>a+p.amount,0))}<small>${cur()}</small>`,'','check')}${kpi(T('طلبات استرجاع','Refund requests'),pend.length,'','refresh')}</div>
  <div class="g2"><div><div class="tb">${searchBox('lgQ',S.f.ledger.q,T('ابحث برقم الإيصال أو العقد…','Search receipt or contract…'),'lg')}</div>${table([{h:T('الإيصال','Receipt'),f:p=>`<b class="num" dir="ltr">${p.receipt}</b>`},{h:T('العقد','Contract'),f:p=>`<span dir="ltr">${ctOf(p.c).no}</span>`},{h:T('الدافع','Payer'),f:p=>uname(ctOf(p.c).tenant)},{h:T('النوع','Type'),f:p=>p.kind==='fee'?T('رسوم','Fee'):T('إيجار','Rent')},{h:T('المبلغ','Amount'),f:p=>`<b class="num">${money(p.amount)}</b>`},{h:T('التاريخ','Date'),f:p=>fd(p.paidOn)}],l)}</div>
  <div class="col"><div class="card"><div class="ch"><h3>${T('طلبات الاسترجاع','Refund requests')}</h3></div>${pend.map(r=>`<div class="li"><span class="ii warn">${ic('refresh',16)}</span><div class="tx"><div class="sm b">${ctOf(r.c).no} · ${money(r.amount)}</div><div class="xs mut3">${L(r.why)}</div></div>${btn(T('اعتماد','Approve'),'refund',{id:r.id,v:'ok'},'sm pri')}${ibtn('x','refund',{id:r.id,v:'no'},T('رفض','Reject'))}</div>`).join('')||empty(T('لا طلبات','No requests'),'','check')}</div>
  <div class="card"><div class="ch"><h3>${T('جدول الرسوم','Fee schedule')}</h3></div><div class="cb col">${field(T('رسوم تسجيل عقد جديد (د.ب)','New contract registration fee (BD)'),inp('feeReg',DB.fees.reg,'number','min="0"'))}${field(T('رسوم تجديد العقد (د.ب)','Renewal fee (BD)'),inp('feeRen',DB.fees.renew,'number','min="0"'))}<div class="hint">${T('تُطبَّق هذه القيم فوراً على العقود الجديدة.','These values apply immediately to new contracts.')}</div><button class="btn pri" data-a="feesave">${T('حفظ الرسوم','Save fees')}</button></div></div></div></div>`;
}
IN.lg=v=>{S.f.ledger.q=v;renderView()};
A.feesave=async()=>{try{await afterMutation(API.post('/api/settings',{reg:+val('feeReg')||0,renew:+val('feeRen')||0}));toast(T('تم حفظ الرسوم','Fees saved'))}catch(e){apiError(e,'تعذّر الحفظ','Could not save')}};
A.refund=async d=>{try{await afterMutation(API.post('/api/refunds/'+d.id,{approve:d.v==='ok'}));toast(d.v==='ok'?T('تم اعتماد الاسترجاع','Refund approved'):T('تم رفض الطلب','Request rejected'))}catch(e){apiError(e,'تعذّر التنفيذ','Could not process')}};

/* tickets */
V.tickets=()=>{
  const F=S.f.tickets;const l=DB.tickets.filter(t=>F.st==='all'||t.st===F.st);const c=s=>s==='all'?DB.tickets.length:DB.tickets.filter(t=>t.st===s).length;
  return pageHead(T('الدعم والنزاعات','Support & disputes'),T('تذاكر المستخدمين والنزاعات بين المؤجرين والمستأجرين','User tickets and landlord–tenant disputes'))+
  `<div class="tb">${seg([['all',T('الكل','All'),c('all')],['open',T('مفتوحة','Open'),c('open')],['pending',T('بانتظار الرد','Pending'),c('pending')],['resolved',T('محلولة','Resolved'),c('resolved')]],F.st,'seg','data-k="tickets.st"')}</div>`+
  table([{h:T('التذكرة','Ticket'),f:t=>`<b>${esc(t.subj)}</b><small class="xs mut3" style="display:block">${t.id}</small>`},{h:T('من','From'),f:t=>`<div class="ent">${ava(uname(t.from))}${uname(t.from)}</div>`},{h:T('التصنيف','Category'),f:t=>chip(rawL(TCAT[t.cat]),'nd')},{h:T('الأولوية','Priority'),f:t=>PRI(t.pri)},{h:T('المسؤول','Assignee'),f:t=>t.asg?uname(t.asg):`<span class="mut3">${T('غير معيّن','Unassigned')}</span>`},{h:T('الحالة','Status'),f:t=>TSTATUS(t.st)},{h:T('منذ','Age'),f:t=>rel(t.created)}],l.map(t=>Object.assign({},t,{_a:'opentk'})));
};
A.opentk=d=>openModal('ticket',{id:d.id});
MOD.ticket=d=>{const t=DB.tickets.find(x=>x.id===d.id);
  return {sheet:1,title:`${t.id}`,body:`<h4 style="margin-bottom:8px">${esc(t.subj)}</h4><div class="row wrapf" style="margin-bottom:16px">${TSTATUS(t.st)}${PRI(t.pri)}${chip(rawL(TCAT[t.cat]),'nd')}</div>
   <div class="col" style="gap:10px">${t.msgs.map(m=>{const staff=userOf(m.f).role==='admin';return `<div style="align-self:${staff?'flex-end':'flex-start'};max-width:88%;background:${staff?'var(--tealsoft)':'var(--sf2)'};border-radius:12px;padding:10px 14px"><div class="xs mut3">${uname(m.f)} · ${rel(m.t)}</div><div class="sm">${esc(m.x)}</div></div>`}).join('')}</div>
   <hr class="hr"><div class="fg">${field(T('الحالة','Status'),sel('tkSt',[['open',T('مفتوحة','Open')],['pending',T('بانتظار الرد','Pending')],['resolved',T('محلولة','Resolved')]],t.st))}${field(T('المسؤول','Assignee'),sel('tkAs',[['',T('غير معيّن','Unassigned')],...DB.users.filter(u=>u.role==='admin').map(u=>[u.id,L(u.name)])],t.asg||''))}${field(T('الرد','Reply'),`<textarea class="ta" id="tkRep" style="min-height:80px" placeholder="${T('اكتب ردك…','Write a reply…')}"></textarea>`,'full')}</div>`,
   foot:`<button class="btn" data-a="close">${T('إغلاق','Close')}</button><button class="btn pri" data-a="tksave" data-id="${t.id}">${ic('send',16)}${T('حفظ وإرسال','Save & send')}</button>`}};
A.tksave=async d=>{try{await afterMutation(API.post('/api/tickets/'+d.id,{status:val('tkSt'),assignee:val('tkAs')||null,reply:val('tkRep').trim()||undefined}));closeModal();toast(T('تم تحديث التذكرة','Ticket updated'))}catch(e){apiError(e,'تعذّر التحديث','Could not update the ticket')}};

/* integrations */
V.integrations=()=>pageHead(T('التكامل مع الجهات','Integrations'),T('ربط المنصة بالجهات الحكومية والمالية ومتابعة حالة الاتصال','Connect the platform to government and financial bodies and monitor connection health'))+
  `<div class="g4" style="grid-template-columns:repeat(auto-fill,minmax(320px,1fr))">${DB.integ.map(i=>`<div class="card"><div class="cb col"><div class="row"><span class="av ${i.on?'':'b'}">${ic('plug',18)}</span><div style="flex:1"><b>${L(i.name)}</b><div class="xs mut3">${L(i.desc)}</div></div>${sw(i.on,'integ','data-id="'+i.id+'"')}</div>
   <div class="row wrapf">${chip(!i.on?T('متوقف','Off'):i.st==='ok'?T('متصل','Online'):T('بطيء','Degraded'),!i.on?'':i.st==='ok'?'ok':'warn')}${i.on?`<span class="xs mut3">${i.ms} ms · ${T('آخر مزامنة','last sync')} ${T(`${i.last} د`,`${i.last}m`)}</span>`:''}</div>
   <div class="row">${btn(T('اختبار الاتصال','Test connection'),'inttest',{id:i.id},'sm','zap')}${i.on?chip(T('مفعّل','Enabled'),'ok'):chip(T('معطّل','Disabled'),'')}</div></div></div>`).join('')}</div>`;
CH.integ=async el=>{const on=el.checked;try{await API.post('/api/integrations/'+el.dataset.id+'/toggle',{enabled:on});await refresh();toast(on?T('تم تفعيل الربط','Integration enabled'):T('تم إيقاف الربط','Integration disabled'))}catch(e){el.checked=!on;apiError(e,'تعذّر التنفيذ','Could not update')}};
A.inttest=async d=>{const i=DB.integ.find(x=>x.id===d.id);if(!i.on){toast(T('فعّل الربط أولاً','Enable the integration first'),true);return}toast(T('جارٍ الاختبار…','Testing…'));try{const r=await API.post('/api/integrations/'+d.id+'/test');toast(r.status==='ok'?T('الاتصال سليم — '+r.ms+' ms','Connection healthy — '+r.ms+' ms'):T('الاتصال بطيء — '+r.ms+' ms','Connection slow — '+r.ms+' ms'),r.status!=='ok')}catch(e){apiError(e,'تعذّر الاختبار','Could not test')}};

/* content */
V.content=()=>{
  const tb=S.tab.content||'faq';
  const body=tb==='faq'?`<div class="card">${DB.faq.map(f=>`<div class="li"><div class="tx"><div class="b sm">${L(f.q)}</div><div class="xs mut3" style="max-height:2.6em;overflow:hidden">${L(f.a)}</div></div>${sw(f.pub,'faqpub','data-id="'+f.id+'"')}${ibtn('edit','modal',{t:'faqedit',id:f.id},T('تعديل','Edit'))}${ibtn('trash','modal',{t:'confirm',title:T('حذف السؤال','Delete question'),text:T('سيُحذف السؤال من صفحة المساعدة.','The question will be removed from the help page.'),act:'delfaq',id:f.id,danger:1,label:T('حذف','Delete')},T('حذف','Delete'))}</div>`).join('')}</div>`
  :tb==='tpl'?table([{h:T('القالب','Template'),f:t=>`<b>${L(t.name)}</b>`},{h:T('الإصدار','Version'),f:t=>`v${t.ver}`},{h:T('آخر تحديث','Updated'),f:t=>fd(t.upd)},{h:T('الاستخدام','Uses'),f:t=>fmt(t.uses)},{h:T('الحالة','Status'),f:t=>t.pub?chip(T('منشور','Published'),'ok'):chip(T('مسودة','Draft'),'warn')},{h:'',c:'ac',f:t=>ibtn('edit','modal',{t:'tpledit',id:t.id},T('تعديل','Edit'))}],DB.templates)
  :`<div class="g2e" style="margin-top:0">${DB.msgs.map(m=>`<div class="card"><div class="ch"><h3>${L(m.ev)}</h3>${ibtn('edit','modal',{t:'msgedit',id:m.id},T('تعديل','Edit'))}</div><div class="cb col" style="gap:8px"><div class="sm">${esc(m.ar)}</div><div class="sm mut" dir="ltr" style="text-align:start">${esc(m.en)}</div></div></div>`).join('')}</div>`;
  return pageHead(T('المحتوى والقوالب','Content & templates'),T('إدارة الأسئلة الشائعة وقوالب العقود ونصوص الإشعارات','Manage FAQs, contract templates and notification texts'),tb==='faq'?btn(T('سؤال جديد','New question'),'modal',{t:'faqedit'},'pri','plus'):'')+tabs([['faq',T('الأسئلة الشائعة','FAQ')],['tpl',T('قوالب العقود','Contract templates')],['msg',T('نصوص الإشعارات','Notification texts')]],tb,'content')+body;
};
CH.faqpub=async el=>{const on=el.checked;try{await API.post('/api/faq/'+el.dataset.id+'/publish',{published:on});toast(on?T('تم النشر','Published'):T('تم إخفاء السؤال','Unpublished'))}catch(e){el.checked=!on;apiError(e,'تعذّر التنفيذ','Could not update')}};
A.delfaq=async d=>{try{await afterMutation(API.del('/api/faq/'+d.id));closeModal();toast(T('تم الحذف','Deleted'))}catch(e){apiError(e,'تعذّر الحذف','Could not delete')}};
MOD.faqedit=d=>{const f=d.id?DB.faq.find(x=>x.id===d.id):{q:{ar:'',en:''},a:{ar:'',en:''}};return {title:d.id?T('تعديل سؤال','Edit question'):T('سؤال جديد','New question'),body:`<div class="fg">${field(T('السؤال (عربي)','Question (Arabic)'),inp('fqA',f.q.ar,'text','data-focus'),'full')}${field(T('السؤال (English)','Question (English)'),inp('fqE',f.q.en,'text','dir="ltr" style="text-align:start"'),'full')}${field(T('الإجابة (عربي)','Answer (Arabic)'),`<textarea class="ta" id="faA">${esc(f.a.ar)}</textarea>`,'full')}${field(T('الإجابة (English)','Answer (English)'),`<textarea class="ta" id="faE" dir="ltr">${esc(f.a.en)}</textarea>`,'full')}</div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="faqsave" data-id="${d.id||''}">${T('حفظ','Save')}</button>`}};
A.faqsave=async d=>{const qAr=val('fqA').trim(),aAr=val('faA').trim();if(!qAr||!aAr){toast(T('أكمل السؤال والإجابة بالعربية','Complete the Arabic question and answer'),true);return}
  try{await afterMutation(API.post('/api/faq',{id:d.id||undefined,qAr,qEn:val('fqE').trim(),aAr,aEn:val('faE').trim()}));closeModal();toast(T('تم الحفظ','Saved'))}catch(e){apiError(e,'تعذّر الحفظ','Could not save')}};
MOD.tpledit=d=>{const t=DB.templates.find(x=>x.id===d.id);return {title:L(t.name),cls:'narrow',body:`<div class="col">${field(T('اسم القالب','Template name'),inp('tpN',rawL(t.name)))}<label class="opt"><input type="checkbox" id="tpP" ${t.pub?'checked':''}><span class="sm">${T('منشور للمستخدمين','Published to users')}</span></label>${field(T('ملاحظات التعديل','Change notes'),`<textarea class="ta" id="tpNote" style="min-height:70px"></textarea>`)}<div class="hint">${T('عند الحفظ يرتفع رقم الإصدار تلقائياً.','Saving bumps the version number automatically.')}</div></div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="tplsave" data-id="${t.id}">${T('حفظ إصدار جديد','Save new version')}</button>`}};
A.tplsave=async d=>{try{const r=await API.post('/api/templates/'+d.id,{name:val('tpN').trim(),published:chk('tpP')});await refresh();closeModal();toast(T('تم حفظ الإصدار v'+r.template.ver,'Saved version v'+r.template.ver))}catch(e){apiError(e,'تعذّر الحفظ','Could not save')}};
MOD.msgedit=d=>{const m=DB.msgs.find(x=>x.id===d.id);return {title:L(m.ev),body:`<div class="fg">${field(T('النص (عربي)','Text (Arabic)'),`<textarea class="ta" id="mgA" data-focus>${esc(m.ar)}</textarea>`,'full')}${field(T('النص (English)','Text (English)'),`<textarea class="ta" id="mgE" dir="ltr">${esc(m.en)}</textarea>`,'full')}</div><div class="hint">${T('المتغيرات المتاحة:','Available variables:')} <span dir="ltr">{date} {amount} {no} {receipt}</span></div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="msgsave" data-id="${m.id}">${T('حفظ','Save')}</button>`}};
A.msgsave=async d=>{try{await afterMutation(API.post('/api/messages/'+d.id,{textAr:val('mgA'),textEn:val('mgE')}));closeModal();toast(T('تم الحفظ','Saved'))}catch(e){apiError(e,'تعذّر الحفظ','Could not save')}};

/* roles */
V.roles=()=>pageHead(T('الأدوار والصلاحيات','Roles & permissions'),T('حدّد ما يمكن لكل دور فعله داخل لوحة الإدارة','Define what each role can do in the admin console'),btn(T('دور جديد','New role'),'modal',{t:'roleadd'},'pri','plus'))+
  `<div class="tw"><table class="rt mx" style="min-width:${300+DB.roles.length*110}px"><thead><tr><th>${T('الصلاحية','Permission')}</th>${DB.roles.map(r=>`<th>${L(r)}</th>`).join('')}</tr></thead><tbody>${DB.perms.map(p=>`<tr><td data-label="${T('الصلاحية','Permission')}">${T(p[1],p[2])}</td>${DB.roles.map(r=>`<td data-label="${L(r)}"><label class="sw"><input type="checkbox" ${DB.perm[r.id][p[0]]?'checked':''} ${r.id==='super'?'disabled':''} data-ch="perm" data-r="${r.id}" data-p="${p[0]}"><i></i></label></td>`).join('')}</tr>`).join('')}</tbody></table></div>
  <div class="hint" style="margin-top:10px">${T('دور «مدير النظام» يملك كل الصلاحيات ولا يمكن تعديله.','The “Super admin” role has all permissions and cannot be edited.')}</div>`;
CH.perm=async el=>{const on=el.checked;try{await API.post('/api/roles/'+el.dataset.r+'/perm',{perm:el.dataset.p,allowed:on});DB.perm[el.dataset.r][el.dataset.p]=on;toast(T('تم حفظ الصلاحية','Permission saved'))}catch(e){el.checked=!on;apiError(e,'تعذّر الحفظ','Could not save')}};
MOD.roleadd=()=>({title:T('دور جديد','New role'),cls:'narrow',body:`<div class="col">${field(T('اسم الدور (عربي)','Role name (Arabic)'),inp('rlA','','text','data-focus'))}${field(T('اسم الدور (English)','Role name (English)'),inp('rlE','','text','dir="ltr" style="text-align:start"'))}</div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="rolesave">${T('إنشاء','Create')}</button>`});
A.rolesave=async()=>{const a=val('rlA').trim();if(!a){toast(T('أدخل اسم الدور','Enter a role name'),true);return}try{await afterMutation(API.post('/api/roles',{nameAr:a,nameEn:val('rlE').trim()||a}));closeModal();toast(T('تم إنشاء الدور','Role created'))}catch(e){apiError(e,'تعذّر الإنشاء','Could not create the role')}};

/* reports (admin) */
function reportsAdmin(){
  const st={};DB.contracts.forEach(c=>{const s=cst(c);st[s]=(st[s]||0)+1});const cols={active:'var(--teal)',expiring:'var(--warn)',pending_sign:'var(--info)',pending_pay:'var(--info)',under_review:'var(--gold)',expired:'var(--ink3)',disputed:'var(--bad)',terminated:'var(--bad)',rejected:'var(--bad)',draft:'var(--ink3)'};
  return pageHead(T('التقارير','Reports'),T('مؤشرات الأداء والنمو على مستوى المنصة','Platform-wide performance and growth indicators'),btn(T('تصدير المستخدمين','Export users'),'modal',{t:'export',kind:'users'},'','download')+btn(T('تصدير العقود','Export contracts'),'modal',{t:'export',kind:'contracts'},'pri','download'))+
  `<div class="kpis">${kpi(T('عقود موقّعة إلكترونياً','E-signed leases'),signedPct(),T(`${DB.contracts.filter(c=>c.signedL&&c.signedT).length} من ${DB.contracts.length}`,`${DB.contracts.filter(c=>c.signedL&&c.signedT).length} of ${DB.contracts.length}`),'pen')}${kpi(T('نسبة التجديد','Renewal rate'),renewPct(),T(`${DB.contracts.filter(c=>c.renewal&&c.renewal.state==='accepted').length} تجديد`,`${DB.contracts.filter(c=>c.renewal&&c.renewal.state==='accepted').length} renewed`),'refresh')}${kpi(T('نسبة التحصيل','Collection rate'),collPct(),T('من الإيجار المستحق','of rent due'),'check')}${kpi(T('إيراد الرسوم','Fee revenue'),`${fmt(feeRevenue())}<small>${cur()}</small>`,'','coins')}</div>
  <div class="g2"><div class="card"><div class="ch"><h3>${T('إيراد الرسوم شهرياً (د.ب)','Fee revenue per month (BD)')}</h3></div><div class="cb">${barChart(MLAB(12),[feeByMonth()],['var(--brand)'],{label:T('الإيراد','Revenue')})}</div></div>
  <div class="card"><div class="ch"><h3>${T('حالة العقود (العيّنة)','Lease status (sample)')}</h3></div><div class="cb row wrapf" style="justify-content:center;gap:20px">${donut(Object.keys(st).map(k=>({v:st[k],c:cols[k]||'var(--ink3)',l:ST[k]?T(ST[k][0],ST[k][1]):k})),DB.contracts.length,T('عقد','leases'))}<div class="legend" style="flex-direction:column;gap:6px">${Object.keys(st).map(k=>`<span><i style="background:${cols[k]||'var(--ink3)'}"></i>${ST[k]?T(ST[k][0],ST[k][1]):k} ${st[k]}</span>`).join('')}</div></div></div></div>
  <div class="g2e"><div class="card"><div class="ch"><h3>${T('توزيع المستخدمين','User breakdown')}</h3></div><div class="cb">${hbars([{l:T('مؤجرون','Landlords'),v:DB.users.filter(u=>u.role==='landlord').length},{l:T('مستأجرون','Tenants'),v:DB.users.filter(u=>u.role==='tenant').length},{l:T('الإدارة','Staff'),v:DB.users.filter(u=>u.role==='admin').length}],'var(--slate)')}</div></div>
  <div class="card"><div class="ch"><h3>${T('طرق الدفع','Payment methods')}</h3></div><div class="cb">${methBars()}</div></div></div>`;
}

/* audit */
V.audit=()=>{const q=S.f.audit.q.toLowerCase();const l=DB.audit.filter(a=>!q||(a.ar+a.en+uname(a.u)+a.ent).toLowerCase().includes(q));
  return pageHead(T('سجل التدقيق','Audit log'),T('سجل غير قابل للتعديل لكل العمليات الحساسة','A tamper-proof record of every sensitive operation'),btn(T('تصدير','Export'),'modal',{t:'export',kind:'audit'},'','download'))+
  `<div class="tb">${searchBox('auQ',S.f.audit.q,T('ابحث في السجل…','Search the log…'),'au')}</div>`+table([{h:T('الوقت','Time'),f:a=>`<span class="num sm">${fdt(a.t)}</span>`},{h:T('المستخدم','User'),f:a=>`<div class="ent">${ava(uname(a.u))}${uname(a.u)}</div>`},{h:T('العملية','Action'),f:a=>`<b class="sm">${T(a.ar,a.en)}</b>`},{h:T('الكيان','Entity'),f:a=>`<span class="num" dir="ltr">${esc(a.ent)}</span>`},{h:T('قبل','Before'),f:a=>a.before?`<span class="num xs mut3" dir="ltr">${esc(JSON.stringify(a.before))}</span>`:'—'},{h:T('بعد','After'),f:a=>a.after?`<span class="num xs" dir="ltr">${esc(JSON.stringify(a.after))}</span>`:'—'},{h:'IP',f:a=>`<span class="num mut3" dir="ltr">${a.ip}</span>`}],l);
};
IN.au=v=>{S.f.audit.q=v;renderView()};

/* ===== payment gateways (admin) ===== */
const gwProvider=id=>DB.gatewayProviders.find(p=>p.id===id);
V.gateways=()=>{
  const l=DB.gateways||[];
  return pageHead(T('بوابات الدفع','Payment gateways'),T('أضف بوابات الدفع واربطها وفعّلها واختبرها — دون كتابة أي كود','Add, configure, enable and test payment gateways — no code required'),btn(T('إضافة بوابة','Add gateway'),'modal',{t:'gwadd'},'pri','plus'))+
  (l.length?`<div class="g4" style="grid-template-columns:repeat(auto-fill,minmax(320px,1fr))">${l.map(g=>{
    const meta=gwProvider(g.provider);
    return `<div class="card"><div class="cb col"><div class="row"><span class="av" style="background:var(--sf2)">${ic('card',18)}</span><div style="flex:1"><b>${L(g.label)}</b><div class="xs mut3">${L(g.providerName)} · ${esc(g.currency)}</div></div>${g.isDefault?chip(T('افتراضية','Default'),'brand'):''}</div>
    <div class="row wrapf" style="gap:6px">${g.enabled?chip(T('مفعّلة','Enabled'),'ok'):chip(T('معطّلة','Disabled'),'bad')}${g.testMode?chip(T('وضع الاختبار','Test mode'),'warn'):chip(T('وضع حقيقي','Live'),'teal')}${g.hasWebhookSecret?chip(T('إشعارات موقّعة','Signed webhooks'),'info'):''}</div>
    <div class="xs mut3" dir="ltr" style="word-break:break-all">${esc(g.webhookPath)}</div>
    <div class="row wrapf" style="gap:6px"><button class="btn sm" data-a="modal" data-t="gwedit" data-id="${g.id}">${ic('edit',15)}${T('تعديل','Edit')}</button><button class="btn sm" data-a="gwtest" data-id="${g.id}">${ic('plug',15)}${T('اختبار الاتصال','Test connection')}</button>${g.enabled?`<button class="btn sm" data-a="gwtestpay" data-id="${g.id}">${ic('zap',15)}${T('دفعة اختبار','Test payment')}</button>`:''}${!g.isDefault&&g.enabled?`<button class="btn sm ghost" data-a="gwdefault" data-id="${g.id}">${T('اجعلها افتراضية','Make default')}</button>`:''}<button class="btn sm danger" data-a="modal" data-t="confirm" data-title="${esc(T('حذف البوابة','Delete gateway'))}" data-text="${esc(T('سيتم حذف هذه البوابة نهائياً. لا يمكن التراجع.','This gateway will be permanently deleted. This cannot be undone.'))}" data-act="gwdel" data-id="${g.id}" data-danger="1" data-label="${esc(T('حذف','Delete'))}">${ic('trash',15)}</button></div>
    </div></div>`}).join('')}</div>`
  :`<div class="card">${empty(T('لا توجد بوابات دفع','No payment gateways'),T('أضف بوابة دفع لتفعيل تحصيل الإيجارات.','Add a payment gateway to enable rent collection.'),'card')}</div>`)+
  `<div class="hint" style="margin-top:12px">${ic('lock',13)} ${T('تُخزَّن مفاتيح الدفع مشفّرة (AES-256-GCM) ولا تُعرض بعد الحفظ. لا تمرّ بيانات البطاقة عبر إيجاري إطلاقاً.','Gateway credentials are stored encrypted (AES-256-GCM) and never shown again after saving. Card data never passes through Ejari.')}</div>`;
};
function gwFieldInputs(providerId,cfg){
  const meta=gwProvider(providerId);if(!meta)return '';
  return meta.fields.map(f=>{
    // Secret fields are never prefilled: the server only returns a mask, and echoing it back
    // on save would overwrite the real credential. Blank keeps the stored value.
    const v=(cfg&&!f.secret)?(cfg[f.key]||''):'';
    return field(L(f.label)+(f.required?' *':''),inp('gwF_'+f.key,v,f.secret?'password':'text',`dir="ltr" style="text-align:start"${f.placeholder?` placeholder="${esc(f.placeholder)}"`:''}`),'',f.secret?T('اتركه فارغاً للإبقاء على القيمة الحالية.','Leave blank to keep the current value.'):'');
  }).join('');
}
MOD.gwadd=()=>{const provs=DB.gatewayProviders||[];return {title:T('إضافة بوابة دفع','Add a payment gateway'),cls:'wide',body:`<div class="fg">${field(T('المزوّد','Provider'),sel('gwProv',provs.map(p=>[p.id,L(p.name)]),provs[0]&&provs[0].id,'data-ch="gwProv"'))}${field(T('الاسم الظاهر (عربي)','Display name (Arabic)'),inp('gwLa','','text'))}${field(T('الاسم الظاهر (English)','Display name (English)'),inp('gwLe','','text','dir="ltr"'))}${field(T('العملة','Currency'),sel('gwCur',[['BHD','BHD'],['USD','USD'],['AED','AED']],'BHD'))}</div><div id="gwFields" class="fg">${gwFieldInputs(provs[0]&&provs[0].id,null)}</div><div class="fg">${field(T('السرّ الموقّع للإشعارات (اختياري)','Webhook signing secret (optional)'),inp('gwHook','','text','dir="ltr" style="text-align:start"'),'',T('اتركه فارغاً ليُولَّد تلقائياً.','Leave blank to generate one automatically.'))}</div><div class="col"><label class="opt"><input type="checkbox" id="gwEn" checked><span class="sm">${T('مفعّلة','Enabled')}</span></label><label class="opt"><input type="checkbox" id="gwTest" checked><span class="sm">${T('وضع الاختبار','Test mode')}</span></label><label class="opt"><input type="checkbox" id="gwDef"><span class="sm">${T('اجعلها البوابة الافتراضية','Make this the default gateway')}</span></label></div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="gwsave">${T('حفظ البوابة','Save gateway')}</button>`}};
MOD.gwedit=d=>{const g=DB.gateways.find(x=>x.id===d.id);const meta=gwProvider(g.provider);return {title:L(g.label),cls:'wide',body:`<div class="fg">${field(T('المزوّد','Provider'),`<input class="in" value="${esc(L(meta?meta.name:{ar:g.provider,en:g.provider}))}" readonly>`)}${field(T('الاسم الظاهر (عربي)','Display name (Arabic)'),inp('gwLa',g.label.ar,'text'))}${field(T('الاسم الظاهر (English)','Display name (English)'),inp('gwLe',g.label.en,'text','dir="ltr"'))}${field(T('العملة','Currency'),sel('gwCur',[['BHD','BHD'],['USD','USD'],['AED','AED']],g.currency))}</div><div id="gwFields" class="fg">${gwFieldInputs(g.provider,g.configured)}</div><div class="fg">${field(T('السرّ الموقّع للإشعارات','Webhook signing secret'),inp('gwHook','','text','dir="ltr" style="text-align:start" placeholder="'+(g.hasWebhookSecret?T('مضبوط — اتركه فارغاً للإبقاء','set — leave blank to keep'):T('غير مضبوط','not set'))+'"'))}</div><div class="col"><label class="opt"><input type="checkbox" id="gwEn" ${g.enabled?'checked':''}><span class="sm">${T('مفعّلة','Enabled')}</span></label><label class="opt"><input type="checkbox" id="gwTest" ${g.testMode?'checked':''}><span class="sm">${T('وضع الاختبار','Test mode')}</span></label><label class="opt"><input type="checkbox" id="gwDef" ${g.isDefault?'checked':''}><span class="sm">${T('اجعلها البوابة الافتراضية','Make this the default gateway')}</span></label></div>`,foot:`<button class="btn" data-a="close">${T('إلغاء','Cancel')}</button><button class="btn pri" data-a="gwsave" data-id="${g.id}">${T('حفظ','Save')}</button>`}};
CH.gwProv=()=>{const el=$('#gwFields');if(el)el.innerHTML=gwFieldInputs(val('gwProv'),null)};
function gwReadConfig(){
  const cur=S.modal.d&&S.modal.d.id?DB.gateways.find(x=>x.id===S.modal.d.id):null;
  const meta=gwProvider(cur?cur.provider:val('gwProv'));
  const cfg={};if(meta)meta.fields.forEach(f=>{const e=document.getElementById('gwF_'+f.key);if(e&&e.value!=='')cfg[f.key]=e.value});return cfg;
}
A.gwsave=async d=>{
  const body={labelAr:val('gwLa').trim(),labelEn:val('gwLe').trim(),currency:val('gwCur'),enabled:chk('gwEn'),testMode:chk('gwTest'),isDefault:chk('gwDef'),config:gwReadConfig(),webhookSecret:val('gwHook').trim()||undefined};
  if(!d.id)body.provider=val('gwProv');
  try{await API.post(d.id?'/api/gateways/'+d.id:'/api/gateways',body);await refresh();closeModal();renderView();toast(T('تم حفظ البوابة','Gateway saved'))}
  catch(e){const m={missing_field:T('أكمل الحقول المطلوبة','Complete the required fields'),unknown_provider:T('مزوّد غير معروف','Unknown provider')};apiError(e,m[e.error]||'تعذّر الحفظ',m[e.error]||'Could not save')}};
A.gwdel=async d=>{try{await API.del('/api/gateways/'+d.id);await refresh();closeModal();renderView();toast(T('تم حذف البوابة','Gateway deleted'))}catch(e){const m={gateway_in_use:T('لا يمكن الحذف: البوابة مستخدمة في عمليات دفع','Cannot delete: the gateway is used by payments')};apiError(e,m[e.error]||'تعذّر الحذف',m[e.error]||'Could not delete')}};
A.gwdefault=async d=>{try{await API.post('/api/gateways/'+d.id,{isDefault:true});await refresh();renderView();toast(T('تم تعيين البوابة الافتراضية','Default gateway updated'))}catch(e){apiError(e,'تعذّر التعيين','Could not set default')}};
A.gwtest=async d=>{toast(T('جارٍ اختبار الاتصال…','Testing the connection…'));try{const r=await API.post('/api/gateways/'+d.id+'/test');toast(r.ok?T('الاتصال سليم — '+r.latencyMs+' مللي ثانية','Connection healthy — '+r.latencyMs+' ms'):T('فشل الاتصال','Connection failed'),!r.ok)}catch(e){apiError(e,'تعذّر الاختبار','Could not test')}};
A.gwtestpay=async d=>{try{const r=await API.post('/api/gateways/'+d.id+'/test-payment',{amount:1});await refresh();toast(T('دفعة اختبار: '+r.intent.status,'Test payment: '+r.intent.status),r.intent.status!=='paid')}catch(e){apiError(e,'تعذّر إجراء الدفعة','Could not run the test payment')}};

/* settings */
V.settings=()=>{const f=DB.fees;const s=DB.settings||{};const co=s.company||{ar:'',en:''};const sup=s.support||{};const nt=s.notify||{};const em=s.email||{};
  return pageHead(T('الإعدادات','Settings'),T('إعدادات النظام والأمان وحماية البيانات','System, security and data-protection settings'),btn(T('حفظ الإعدادات','Save settings'),'setsave','','pri','check'))+
  `<div class="g2e" style="margin-top:0"><div class="col">
   <div class="card"><div class="ch"><h3>${T('بيانات الشركة','Company information')}</h3></div><div class="cb fg">${field(T('الاسم (عربي)','Name (Arabic)'),inp('stCoAr',co.ar))}${field(T('الاسم (English)','Name (English)'),inp('stCoEn',co.en,'text','dir="ltr"'))}${field(T('العملة','Currency'),sel('stCur',[['BHD','BHD — دينار بحريني'],['USD','USD'],['AED','AED'],['SAR','SAR']],s.currency||'BHD'))}${field(T('المنطقة الزمنية','Timezone'),sel('stTz',[['Asia/Bahrain','Asia/Bahrain'],['Asia/Riyadh','Asia/Riyadh'],['Asia/Dubai','Asia/Dubai'],['UTC','UTC']],s.timezone||'Asia/Bahrain'))}${field(T('اللغة الافتراضية','Default locale'),sel('stLoc',[['ar','العربية'],['en','English']],s.locale||'ar'))}${field(T('بريد الدعم','Support email'),inp('stSupMail',sup.email||'','email','dir="ltr" style="text-align:start"'))}${field(T('هاتف الدعم','Support phone'),inp('stSupPhone',sup.phone||'','tel','dir="ltr" style="text-align:start"'))}</div></div>
   <div class="card"><div class="ch"><h3>${T('التنبيهات التلقائية','Automatic alerts')}</h3></div><div class="cb fg">${field(T('تذكير قبل الاستحقاق (أيام)','Reminder before due date (days)'),inp('stRem',f.remind,'number','min="0"'))}${field(T('تكرار تذكير المتأخرات (أيام)','Overdue reminder every (days)'),inp('stLate',f.late,'number','min="1"'))}</div>
   <div class="cb col" style="border-top:1px solid var(--line)">${[['notifyRentDue',nt.rentDue,T('تنبيه استحقاق الإيجار','Rent due alerts')],['notifyPayment',nt.payment,T('تأكيد الدفع','Payment confirmations')],['notifyExpiry',nt.expiry,T('قرب انتهاء العقود','Lease expiry alerts')],['notifyRenewal',nt.renewal,T('طلبات التجديد','Renewal requests')],['notifyMaintenance',nt.maintenance,T('تحديثات الصيانة','Maintenance updates')]].map(x=>`<div class="row"><div style="flex:1"><div class="b">${x[2]}</div></div>${sw(!!x[1],'setflag','data-k="'+x[0]+'"')}</div>`).join('')}</div></div>
   <div class="card"><div class="ch"><h3>${T('إعدادات البريد','Email settings')}</h3></div><div class="cb col"><div class="row"><div style="flex:1"><div class="b">${T('تفعيل إرسال البريد','Enable outgoing email')}</div><div class="xs mut3">${T('عند التعطيل تُسجَّل الإشعارات داخلياً فقط.','When disabled, notifications are recorded internally only.')}</div></div>${sw(!!em.enabled,'setflag','data-k="emailEnabled"')}</div><div class="fg">${field(T('خادم SMTP','SMTP host'),inp('stSmtpHost',em.host||'','text','dir="ltr" style="text-align:start"'))}${field(T('المنفذ','Port'),inp('stSmtpPort',em.port||587,'number','min="1"'))}${field(T('المستخدم','Username'),inp('stSmtpUser',em.user||'','text','dir="ltr" style="text-align:start"'))}${field(T('المرسل','From address'),inp('stSmtpFrom',em.from||'','email','dir="ltr" style="text-align:start"'))}</div></div></div>
   <div class="card"><div class="ch"><h3>${T('الأمان','Security')}</h3></div><div class="cb col"><div class="row"><div style="flex:1"><div class="b">${T('إلزام الموظفين بالتحقق بخطوتين','Require 2-step verification for staff')}</div></div>${sw(f.twofa,'setflag','data-k="twofa"')}</div>${field(T('مهلة الجلسة (دقائق)','Session timeout (minutes)'),sel('stSess',[[15,'15'],[30,'30'],[60,'60']],f.session))}${field(T('عناوين IP المسموحة للإدارة','Admin IP allow-list'),`<textarea class="ta" id="stIp" dir="ltr" style="min-height:70px" placeholder="10.0.0.0/8, 203.0.113.7">${esc(f.adminIp||'')}</textarea>`,'',T('اكتب عنواناً واحداً أو شبكة CIDR في كل سطر. اتركه فارغاً لإلغاء القيد.','One IP or CIDR network per line. Leave empty to disable. Enforced on every admin request.'))}</div></div></div>
  <div class="col"><div class="card"><div class="ch"><h3>${T('البيانات والخصوصية','Data & privacy')}</h3></div><div class="cb col">${field(T('مدة الاحتفاظ بالسجلات (شهراً)','Record retention (months)'),inp('stRet',f.retention,'number','min="12"'))}<div class="hint">${T('لتصدير بيانات مستخدم، افتح ملف المستخدم من شاشة المستخدمين واضغط «تصدير بيانات المستخدم».','To export a user’s data, open the user from the Users screen and press “Export user data”.')}</div><div class="hint">${T('تُعالج البيانات الشخصية وفق أنظمة حماية البيانات المعمول بها.','Personal data is processed in line with applicable data-protection rules.')}</div></div></div>
   <div class="card"><div class="ch"><h3>${T('بوابات الدفع','Payment gateways')}</h3></div><div class="cb col"><div class="row">${ic('card',18)}<div style="flex:1"><div class="b">${T((DB.gateways||[]).filter(g=>g.enabled).length+' بوابة مفعّلة',''+((DB.gateways||[]).filter(g=>g.enabled).length)+' enabled gateways')}</div><div class="xs mut3">${T('أضف واختبر بوابات الدفع من شاشة مخصّصة.','Add and test gateways from a dedicated screen.')}</div></div><button class="btn sm" data-a="nav" data-v="gateways">${T('إدارة','Manage')}</button></div></div></div>
   <div class="card"><div class="ch"><h3>${T('النسخ الاحتياطي','Backups')}</h3></div><div class="cb col"><div class="row">${ic('history',18)}<div style="flex:1"><div class="b" id="bkT">${T('التخزين','Storage')}: SQLite (WAL) · data/ejari.db</div><div class="xs mut3">${T('يُكتب كل تغيير فوراً على القرص','Every change is written to disk immediately')}</div></div><button class="btn sm" data-a="runbackup" id="bkB">${T('نسخ الآن','Back up now')}</button></div></div></div>
   <div class="card"><div class="cb row"><div style="flex:1"><div class="b">${T('وضع الصيانة','Maintenance mode')}</div><div class="xs mut3">${T('يعرض رسالة توقف مؤقت للمستخدمين','Shows users a temporary downtime notice')}</div></div>${sw(f.maintenanceMode,'setflag','data-k="maintenanceMode"')}</div></div></div></div>`;
};
CH.setflag=async el=>{const on=el.checked;try{await API.post('/api/settings',{[el.dataset.k]:on});if(DB.fees[el.dataset.k]!==undefined)DB.fees[el.dataset.k]=on;if(DB.settings){const m={notifyRentDue:['notify','rentDue'],notifyPayment:['notify','payment'],notifyExpiry:['notify','expiry'],notifyRenewal:['notify','renewal'],notifyMaintenance:['notify','maintenance'],emailEnabled:['email','enabled']};const p=m[el.dataset.k];if(p)DB.settings[p[0]][p[1]]=on}toast(T('تم حفظ التغيير','Change saved'))}catch(e){el.checked=!on;apiError(e,'تعذّر الحفظ','Could not save')}};
A.setsave=async()=>{try{const r=await API.post('/api/settings',{remind:+val('stRem')||0,late:+val('stLate')||1,session:+val('stSess'),retention:+val('stRet')||60,adminIp:val('stIp').trim(),companyAr:val('stCoAr').trim(),companyEn:val('stCoEn').trim(),currency:val('stCur'),timezone:val('stTz'),locale:val('stLoc'),supportEmail:val('stSupMail').trim(),supportPhone:val('stSupPhone').trim(),smtpHost:val('stSmtpHost').trim(),smtpPort:+val('stSmtpPort')||587,smtpUser:val('stSmtpUser').trim(),smtpFrom:val('stSmtpFrom').trim()});await refresh();if(r.settings)DB.settings=r.settings;toast(T('تم حفظ الإعدادات','Settings saved'))}catch(e){apiError(e,'تعذّر الحفظ','Could not save')}};
A.runbackup=()=>toast(T('النسخ الاحتياطي يتم تلقائياً على مستوى ملف قاعدة البيانات (SQLite WAL)','Backups happen automatically at the database (SQLite WAL) level'));
